/bin/bash -lc "python3 - <<'PY'
import ast,json,hashlib,difflib
from pathlib import Path
root=Path('/workspace')
p=json.loads((root/'proposal.json').read_text())
r=json.loads((root/'runtime.json').read_text())
def validate(obj,schema,path='"'$'"'):
 typ=schema.get('type')
 if typ=='object':
  assert isinstance(obj,dict),(path,'object')
  assert set(schema.get('required',[]))<=obj.keys(),(path,'missing required')
  props=schema.get('properties',{})
  if schema.get('additionalProperties') is False: assert obj.keys()<=props.keys(),(path,'extra property')
  for key,value in obj.items():
   if key in props: validate(value,props[key],path+'.'+key)
 elif typ=='array':
  assert isinstance(obj,list),(path,'array')
  assert len(obj)>=schema.get('minItems',0),(path,'minItems')
  for i,value in enumerate(obj):validate(value,schema.get('items',{}),path+'['+str(i)+']')
 elif typ=='string':assert isinstance(obj,str) and len(obj)>=schema.get('minLength',0),(path,'string')
 if 'const' in schema:assert obj==schema['const'],(path,'const')
 if 'enum' in schema:assert obj in schema['enum'],(path,'enum')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
